input.sparql:
SELECT ?sensor ?ts WHERE {
  ?zone a brick:Zone ; brick:hasName "Core_top" .
  OR { ?zone brick:isLocationOf ?sensor . FILTER isBlank(?sensor) }
}

SELECT ?s ?type WHERE {
  ?zone a brick:Zone .
  ?s brick:isPointOf ?zone .
  ?s a ?type .
} LIMIT 200

SELECT ?ref ?tsid WHERE {
  ?p rdf:type brick:Electric_Power_Sensor .
  ?p brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F4_Z01> .
  ?p ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?tsid .
}
